  ('891e6797-e6aa-5a86-917a-a0ae7a03e0ee', null, (select id from public.skills where slug = 'read-g11-character-setting-plot'), null, 'hard',
   $q$What is the function of the details "The handwriting grew firmer. The prices grew smaller"?$q$, $q$[{"text":"They explain why Samir stopped typing, since the handwriting became too hard to read.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"They show that Ilse's business was failing, since she had to lower her prices each year.","is_correct":false,"misconception_token":"misreads-sequence"},{"text":"They show that the letters were written by different people at different times in the shop.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"They mark the movement backward in time and let readers see Ilse growing younger through objects.","is_correct":true}]$q$::jsonb, $q$They mark the movement backward in time and let readers see Ilse growing younger through objects.$q$, $q$Because Samir reads backward, firmer handwriting and smaller prices signal earlier years and a younger Ilse, tracking the reverse chronology. Read in true order, prices rose over time, so the details do not show her lowering them.$q$, 'draft', '605c577f-e39f-5a04-99e4-c02099866ff2')
